void ToUpperInPlace(Span&lt;char&gt; value) { // 将 Span&lt;char&gt; 转换成 Span&lt;ushort&gt;（char 占 2 字节，方便 SIMD 处理） var buffer = MemoryMarshal.Cast&lt;char, ushort&gt;(value); // 获取元素数量（ushort 数量） var elementCount = (uint)buffer.Length; // 每个向量能处理多少个 ushort var numElementsPerVector = (uint)(Unsafe.SizeOf&lt;Vector128&lt;byte&gt;&gt;() / sizeof(ushort)); // 如果支持 SIMD 且数据足够，否则走普通循环 if (Vector128.IsHardwareAccelerated &amp;&amp; elementCount &gt;= numElementsPerVector) { // 有符号最小值 (0x8000) 用于偏移正确比较 ushort sourceSignedMinValue = (ushort)(1 &lt;&lt; (8 * sizeof(ushort) - 1)); // 'a' 的基准向量（所有元素都是 0x8000 + 'a'） var subtractionVector = Vector128.Create((ushort)(sourceSignedMinValue + 'a')); // 26 个字母范围偏移向量（所有元素都是 0x8000 + 26） var comparisonVector = Vector128.Create((ushort)(sourceSignedMinValue + 26)); // 大小写差值向量（0x20，所有元素都是这个值） var caseConversionVector = Vector128.Create((ushort)0x20); // 向量化循环索引 uint i = 0; // 可以整除的元素个数 uint n = elementCount - (elementCount % numElementsPerVector); // 向量化批量处理 for (; i &lt; n; i += numElementsPerVector) { // 加载当前批次的向量数据 var srcVector = Vector128.LoadUnsafe(ref Unsafe.Add(ref MemoryMarshal.GetReference(buffer), (int)i)); // 计算 src - 'a' 基准，并判断是否小于 26（即在 a..z 范围） var matches = SignedLessThan(srcVector - subtractionVector, comparisonVector); // 对匹配的小写字母执行大小写转换（异或 0x20 得到大写） srcVector ^= matches &amp; caseConversionVector; // 存回修改后的向量数据 srcVector.StoreUnsafe(ref Unsafe.Add(ref MemoryMarshal.GetReference(buffer), (int)i)); } // 处理剩余不足一个向量大小的元素 for (; i &lt; elementCount; i++) { // 读取当前字符 ushort c = Unsafe.Add(ref MemoryMarshal.GetReference(buffer), (int)i); // 如果是小写字母则转为大写 if (c is &gt;= 'a' and &lt;= 'z') { c = (ushort)(c - 0x20); } // 写回结果 Unsafe.Add(ref MemoryMarshal.GetReference(buffer), (int)i) = c; } } else { // 非向量化处理，每个元素单独判断 for (int i = 0; i &lt; buffer.Length; i++) { ushort c = buffer[i]; if (c is &gt;= 'a' and &lt;= 'z') { c = (ushort)(c - 0x20); } buffer[i] = c; } } } // 有符号比较（用于判断 a..z 范围） Vector128&lt;ushort&gt; SignedLessThan(Vector128&lt;ushort&gt; left, Vector128&lt;ushort&gt; right) { // 将 ushort 当成 short 做有符号比较，然后再转换回 ushort 掩码 return Vector128.LessThan(left.AsInt16(), right.AsInt16()).AsInt16().AsUInt16(); }

public static class Ascii { public static OperationStatus ToUpper(ReadOnlySpan&lt;byte&gt; source, Span&lt;byte&gt; destination, out int bytesWritten); public static OperationStatus ToLower(ReadOnlySpan&lt;byte&gt; source, Span&lt;byte&gt; destination, out int bytesWritten); public static OperationStatus ToUpperInPlace(Span&lt;byte&gt; value, out int bytesWritten); public static OperationStatus ToLowerInPlace(Span&lt;byte&gt; value, out int bytesWritten); public static OperationStatus ToUpper(ReadOnlySpan&lt;char&gt; source, Span&lt;char&gt; destination, out int charsWritten); public static OperationStatus ToLower(ReadOnlySpan&lt;char&gt; source, Span&lt;char&gt; destination, out int charsWritten); public static OperationStatus ToUpperInPlace(Span&lt;char&gt; value, out int charsWritten); public static OperationStatus ToLowerInPlace(Span&lt;char&gt; value, out int charsWritten); } public enum OperationStatus { /// &lt;summary&gt;The entire input buffer has been processed and the operation is complete.&lt;/summary&gt; Done, /// &lt;summary&gt;The input is partially processed, up to what could fit into the destination buffer. The caller can enlarge the destination buffer, slice the buffers appropriately, and retry.&lt;/summary&gt; DestinationTooSmall, /// &lt;summary&gt;The input is partially processed, up to the last valid chunk of the input that could be consumed. The caller can stitch the remaining unprocessed input with more data, slice the buffers appropriately, and retry.&lt;/summary&gt; NeedMoreData, /// &lt;summary&gt;The input contained invalid bytes which could not be processed. If the input is partially processed, the destination contains the partial result. This guarantees that no additional data appended to the input will make the invalid sequence valid.&lt;/summary&gt; InvalidData, }

[MemoryDiagnoser] public class SimdBenchmark { private float[] _arrA; private float[] _arrB; private float[] _resultArray; private readonly int _dataSize = 1_000_000; [GlobalSetup] public void Setup() { var random = new Random(); _arrA = new float[_dataSize]; _arrB = new float[_dataSize]; _resultArray = new float[_dataSize]; for (int i = 0; i &lt; _dataSize; i++) { _arrA[i] = (float)random.NextDouble() * 10f; _arrB[i] = (float)random.NextDouble() * 10f; } } [Benchmark] public void Vector128CreateAdd() { int simdLength = Vector128&lt;float&gt;.Count; // 4 int i = 0; for (; i &lt;= _dataSize - simdLength; i += simdLength) { var va = Vector128.Create(_arrA[i], _arrA[i + 1], _arrA[i + 2], _arrA[i + 3]); var vb = Vector128.Create(_arrB[i], _arrB[i + 1], _arrB[i + 2], _arrB[i + 3]); (va + vb).CopyTo(_resultArray, i); } for (; i &lt; _dataSize; i++) { _resultArray[i] = _arrA[i] + _arrB[i]; } } [Benchmark] public unsafe void Vector128LoadAdd() { int simdLength = Vector128&lt;float&gt;.Count; int i = 0; fixed (float* pA = _arrA) fixed (float* pB = _arrB) { for (; i &lt;= _dataSize - simdLength; i += simdLength) { var va = Vector128.Load(pA + i); var vb = Vector128.Load(pB + i); (va + vb).CopyTo(_resultArray, i); } } for (; i &lt; _dataSize; i++) { _resultArray[i] = _arrA[i] + _arrB[i]; } } [Benchmark] public void Vector128LoadUnsafeAdd() { int simdLength = Vector128&lt;float&gt;.Count; // 4 int i = 0; for (; i &lt;= _dataSize - simdLength; i += simdLength) { var va = Vector128.LoadUnsafe(ref _arrA[i]); var vb = Vector128.LoadUnsafe(ref _arrB[i]); (va + vb).CopyTo(_resultArray, i); } for (; i &lt; _dataSize; i++) { _resultArray[i] = _arrA[i] + _arrB[i]; } } } public class Program { public static void Main(string[] args) { BenchmarkRunner.Run&lt;SimdBenchmark&gt;(); } }

using System.Runtime.Intrinsics; using BenchmarkDotNet.Attributes; using BenchmarkDotNet.Running; [MemoryDiagnoser] public class SimdBenchmark { private float[] _arrA; private float[] _arrB; private float[] _resultArray; private readonly int _dataSize = 1_000_000; [GlobalSetup] public void Setup() { var random = new Random(); _arrA = new float[_dataSize]; _arrB = new float[_dataSize]; _resultArray = new float[_dataSize]; for (int i = 0; i &lt; _dataSize; i++) { _arrA[i] = (float)random.NextDouble() * 10f; _arrB[i] = (float)random.NextDouble() * 10f; } } [Benchmark] public void NormalAdd() { for (int i = 0; i &lt; _dataSize; i++) { _resultArray[i] = _arrA[i] + _arrB[i]; } } [Benchmark] public void SimdAdd() { // 每次处理 4 个元素 int simdLength = Vector128&lt;float&gt;.Count; // 4 int i = 0; // 处理可被 SIMD 整除的部分 for (; i &lt;= _dataSize - simdLength; i += simdLength) { // 表示从数组的第 i 个位置开始加载数据到向量中, 每次加载 4 个 float var va = Vector128.LoadUnsafe(ref _arrA[i]); var vb = Vector128.LoadUnsafe(ref _arrB[i]); (va + vb).CopyTo(_resultArray, i); } // 处理尾部不足 4 个的元素 for (; i &lt; _dataSize; i++) { _resultArray[i] = _arrA[i] + _arrB[i]; } } } public class Program { public static void Main(string[] args) { BenchmarkRunner.Run&lt;SimdBenchmark&gt;(); } }

