在 C# 的语法演进中，“弃元（Discard）” 以一个简单的下划线 _ 成为了既提升代码可读性，又优化性能的 “双料特性”。它并非单纯的语法简化，而是编译器层面对 “有意忽略的值” 的深度优化 —— 通过明确 “忽略” 的意图，不仅让代码更简洁，更能减少内存分配、降低性能开销。本文将从使用场景、核心优势、性能验证到底层实现，全面解析弃元模式的价值。 什么是弃元模式？ 弃元是 C# 7.0 引入的语法特性，用下划线 _ 表示 “有意忽略的变量”。它不是一个实际的变量，没有分配值，甚至未分配内存，也无法被访问（尝试使用会触发编译错误 CS0103 The name '_' doesn't exist in the current context）。其核心设计初衷是：通过统一的语法明确 “此值无关紧要”，让编译器和开发者都能清晰理解意图。 简单来说，弃元解决了一个长期存在的问题：如何优雅地处理 “必须接收但无需使用” 的值（如 out 参数、元组多余字段、default 分支等）。 应用场景 弃元的应用场景贯穿代码编写的多个环节，核心是 “用 _ 替代所有无需关注的值或变量”，以下是最典型的场景： out 参数：忽略无需使用的输出值 许多方法（如 int.TryParse、DateTime.TryParse）通过 out 参数返回额外结果，但有时我们只需要方法的返回值（如 “是否成功”），无需关注 out 输出。此时弃元可替代临时变量，避免冗余。 示例：验证字符串是否为有效整数，忽略解析结果： string input = " 123 " ; // 用 out _ 忽略解析出的整数，仅关注“是否成功” if ( int .TryParse(input, out _)) { Console.WriteLine( " 输入是有效整数 " ); }

static void TestTupleDeconstruction() { const int loopCount = 10_000_000; var data = (id: 1 , name: " test " , price: 99.9 , stock: 100 ); // 测试元组 // 传统方式：声明所有成员（包含无用项） var watch1 = Stopwatch.StartNew(); for ( int i = 0 ; i &lt; loopCount; i++ ) { var (id, name, price, stock) = data; // 声明4个变量，仅用name和price _ = name + price; } watch1.Stop(); // 弃元方式：忽略无用成员 var watch2 = Stopwatch.StartNew(); for ( int i = 0 ; i &lt; loopCount; i++ ) { var (_, name, price, _) = data; // 仅声明需要的成员 _ = name + price; } watch2.Stop(); Console.WriteLine($ " 传统方式：{watch1.ElapsedMilliseconds} ms " ); Console.WriteLine($ " 弃元方式：{watch2.ElapsedMilliseconds} ms " ); Console.WriteLine($ " 性能提升：{((watch1.ElapsedMilliseconds - watch2.ElapsedMilliseconds) / (double)watch1.ElapsedMilliseconds):P2} " ); }

static void TestOutParameter() { const int loopCount = 10000000 ; // 1000万次循环 string input = " 12345 " ; // 传统方式：用临时变量接收 out 结果 var watch1 = Stopwatch.StartNew(); for ( int i = 0 ; i &lt; loopCount; i++ ) { int temp; int .TryParse(input, out temp); } watch1.Stop(); // 弃元方式：忽略 out 结果 var watch2 = Stopwatch.StartNew(); for ( int i = 0 ; i &lt; loopCount; i++ ) { int .TryParse(input, out _); } watch2.Stop(); Console.WriteLine($ " 传统方式：{watch1.ElapsedMilliseconds} ms " ); Console.WriteLine($ " 弃元方式：{watch2.ElapsedMilliseconds} ms " ); Console.WriteLine($ " 性能提升：{((watch1.ElapsedMilliseconds - watch2.ElapsedMilliseconds) / (double)watch1.ElapsedMilliseconds):P2} " ); }

