static void Train(DataLoader dataloader, NeuralNetwork model, CrossEntropyLoss loss_fn, SGD optimizer) { var size = dataloader.dataset.Count; model.train(); int batch = 0; foreach (var item in dataloader) { var x = item["data"]; var y = item["label"]; // 第一步 // 训练当前图片 var pred = model.call(x); // 通过损失函数得出与真实结果的误差 var loss = loss_fn.call(pred, y); // 第二步，反向传播 loss.backward(); // 计算梯度并优化参数 optimizer.step(); // 清空优化器当前的梯度 optimizer.zero_grad(); // 每 100 次打印损失值和当前训练的图片数量 if (batch % 100 == 0) { loss = loss.item&lt;float&gt;(); // Pytorch 框架会在 x.shape[0] 存储当前批的位置 var current = (batch + 1) * x.shape[0]; Console.WriteLine("loss: {loss.item&lt;float&gt;(),7} [{current,5}/{size,5}]"); } batch++; } }

static void Test(DataLoader dataloader, NeuralNetwork model, CrossEntropyLoss loss_fn) { var size = (int)dataloader.dataset.Count; var num_batches = (int)dataloader.Count; // 将模型设置为评估模式 model.eval(); var test_loss = 0F; var correct = 0F; using (var n = torch.no_grad()) { foreach (var item in dataloader) { var x = item["data"]; var y = item["label"]; // 使用已训练的参数预测测试数据 var pred = model.call(x); // 计算损失值 test_loss += loss_fn.call(pred, y).item&lt;float&gt;(); correct += (pred.argmax(1) == y).type(ScalarType.Float32).sum().item&lt;float&gt;(); } } test_loss /= num_batches; correct /= size; Console.WriteLine("Test Error: \n Accuracy: {(100 * correct):F1}%, Avg loss: {test_loss:F8} \n"); }

